customCss:
/* 作者行：取消外层卡片，两个等宽玻璃块（与上方宫格同语汇） */
.section.thanks-author-row{background:none!important;border:0!important;box-shadow:none!important;padding:0!important;display:grid;grid-template-columns:1fr 1fr;gap:12px}
.thanks-author-row .thanks-author-btn{width:100%;min-height:52px;box-sizing:border-box;display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:0 14px;border-radius:var(--shape-m);background:linear-gradient(135deg,var(--lq-tint) 0%,var(--lq-tint-deep) 100%);border:1px solid color-mix(in srgb,var(--lq-rim-hi) 55%,transparent);box-shadow:0 2px 10px #0a0f2814,inset 0 1px 1px var(--lq-rim-hi),inset -1px -1px 1px var(--lq-rim-lo);color:var(--on-surface);font-size:14px;font-weight:600;line-height:1.1;text-decoration:none;transition:border-color .16s ease,transform .12s cubic-bezier(.2,0,0,1)}
.thanks-author-row .thanks-author-btn:hover{background:linear-gradient(135deg,var(--lq-tint),color-mix(in srgb,var(--primary) 10%,var(--lq-tint-deep)));border-color:color-mix(in srgb,var(--primary) 45%,var(--lq-rim-hi));transform:translateY(-1px)}
.thanks-author-row .thanks-author-btn:active{transform:none}
@media (max-width:360px){.section.thanks-author-row{grid-template-columns:1fr}}
